# SC-NeuroCore — Native Julia dependency manifest audit contracts

"""Audit every dependency in a manifest generated by the installed Julia runtime."""

from __future__ import annotations

import os
from pathlib import Path
import shutil
import subprocess
import sys

import pytest

if sys.version_info >= (3, 11):
    import tomllib
else:
    import tomli as tomllib

from tests.julia_runtimes import require_julia_runtime
from tools.security_scan.locked_dependency_inventory import julia_queries

ROOT = Path(__file__).resolve().parents[2]


def test_julia_queries_cover_runtime_generated_manifest(tmp_path: Path) -> None:
    """Retain every runtime-generated package identity and reject local replacements.

    Parameters
    ----------
    tmp_path : Path
        Private environment, writable depot and subprocess temporary directory.
    """
    runtime = require_julia_runtime("1.13")
    project = ROOT / "src/sc_neurocore/accel/julia/sc_compte_wm_network/Project.toml"
    original = project.read_bytes()
    shutil.copyfile(project, tmp_path / "Project.toml")
    subprocess.run(
        [
            str(runtime),
            "--startup-file=no",
            "--history-file=no",
            "--compiled-modules=existing",
            f"--project={tmp_path}",
            "-e",
            "using Pkg; Pkg.resolve()",
        ],
        cwd=tmp_path,
        env={
            **os.environ,
            "TMPDIR": str(tmp_path),
            "JULIA_LOAD_PATH": "@:@stdlib",
            "JULIA_DEPOT_PATH": os.pathsep.join(
                (str(tmp_path / "depot"), str(Path.home() / ".julia"), "")
            ),
            "JULIA_PKG_PRECOMPILE_AUTO": "0",
            "JULIA_PKG_GC_AUTO": "false",
            "JULIA_NUM_THREADS": "1",
        },
        text=True,
        capture_output=True,
        check=True,
        timeout=240,
    )
    raw = (tmp_path / "Manifest.toml").read_bytes()
    manifest = tomllib.loads(raw.decode("utf-8"))
    assert manifest["manifest_format"] == "2.1"
    assert manifest["registries"]["General"]["uuid"] == "23338594-aafe-5451-b93e-139f81909106"
    expected = tuple(
        {"package": {"ecosystem": "Julia", "name": name}, "version": entry["version"]}
        for name, entries in sorted(manifest["deps"].items())
        for entry in entries
    )
    assert julia_queries(raw) == expected
    assert len(expected) > 1
    with pytest.raises(ValueError, match="exact registry version"):
        julia_queries(raw + b'\n[[deps.Local]]\npath = "local"\nversion = "1.0.0"\n')
    assert project.read_bytes() == original
    assert (tmp_path / "Project.toml").read_bytes() == original
